/*
 * W16a. struct wpa_eapol_key ends at key_id and the frame
 * does not. What follows is three comments, and they are the
 * declaration this table is built from -- which is a WEAKER
 * guarantee than the one the member table has, and is said
 * here rather than left to be discovered: --check fails when
 * a member moves because a member has a type and a name;
 * it fails on these only because the text is matched exactly.
 *
 * 'base' is where the struct ends. 'gap' is the field between
 * base and this one, whose width the negotiated AKM decides,
 * and 'gaps' is every width this tree's own wpa_mic_len() can
 * return. The engine solves for which one applies from the
 * frame's own length; where more than one fits, or none, the
 * field is not swept and the message says which it was.
 */
struct fuzz_var_field {
	const char *name;
	enum fuzz_frame_type frame;
	unsigned int base;
	unsigned int width;
	enum fuzz_field_kind kind;
	int big_endian;
	const char *gap;
	const unsigned short *gaps;
	unsigned int ngaps;
	/* 1 when every return of the function that decides the gap
	 * reduced to a literal, so the candidate set is the whole
	 * of what this tree can produce. 0 means the solver may
	 * have no candidate for a frame that is perfectly valid. */
	int gaps_exact;
};

