/*
 * W16c. An Action frame is one octet of field model and nine
 * protocols of opaque bytes, because the union after the
 * category says nothing about which member a category
 * selects. The tree says: a scope that tests or sets the
 * category against one constant, and the first member of a
 * union member against another, has named the pair. A key
 * that more than one member claims is refused rather than
 * guessed -- the wrong layout would write real values at the
 * wrong offsets under the right names.
 *
 * Offsets are from the CATEGORY octet, so one row reads the
 * same whether the engine holds a whole management frame or
 * an Action body. 'chain_at' is where the member's flexible
 * array begins, or -1 where the member has none -- which is a
 * frame with no element chain, and is not the same as a frame
 * whose chain this engine failed to find.
 */
struct fuzz_action_field {
	const char *name;
	unsigned char off;
	unsigned char width;
	enum fuzz_field_kind kind;
	unsigned char big_endian;
};

struct fuzz_action_layout {
	unsigned char cat;
	/* The code after the category, or -1 for the category's
	 * fallback -- a category whose every member agrees. */
	short code;
	const char *member;
	const struct fuzz_action_field *fields;
	unsigned char nfields;
	short chain_at;
};

