/*
 * W16b. A field's domain is per TARGET, not per frame layout.
 * The 802.1X header's length field is a u16, so 65,536 values
 * and 270 of them a run; at sta-eapol, where the station
 * transmits and the AP parses, the receiver never reads those
 * two octets. That is not weak coverage, it is none, and a
 * run that counts it as covered is wrong in the direction
 * this whole plan is about.
 *
 * The read set is scoped to the FILE holding the receive
 * path, not to the function: a receiver hands the frame to
 * helpers beside it, and a claim scoped to one function would
 * call a field dead that a helper three lines down reads.
 * Over-claiming a read costs a finding; under-claiming one
 * states a falsehood, so the scope errs the first way.
 */
struct fuzz_field_reader {
	const char *frame;
	const char *role;
	const char *fn;
	const char *file;
	const char * const *reads;
};

